/*! qrcode.min.js - Generador QR NATIVO LOCAL (100% Offline / Sin API externa) */
(function(window) {
  'use strict';

  function QR8BitByte(data) {
    this.mode = 4;
    this.data = data;
  }
  QR8BitByte.prototype = {
    getLength: function() { return this.data.length; },
    write: function(buffer) {
      for (var i = 0; i < this.data.length; i++) {
        buffer.put(this.data.charCodeAt(i), 8);
      }
    }
  };

  function QRBitBuffer() {
    this.buffer = [];
    this.length = 0;
  }
  QRBitBuffer.prototype = {
    get: function(index) {
      var bufIndex = Math.floor(index / 8);
      return ((this.buffer[bufIndex] >>> (7 - index % 8)) & 1) === 1;
    },
    put: function(num, length) {
      for (var i = 0; i < length; i++) {
        this.putBit(((num >>> (length - i - 1)) & 1) === 1);
      }
    },
    putBit: function(bit) {
      var bufIndex = Math.floor(this.length / 8);
      if (this.buffer.length <= bufIndex) { this.buffer.push(0); }
      if (bit) { this.buffer[bufIndex] |= (0x80 >>> (this.length % 8)); }
      this.length++;
    }
  };

  function QRCodeModel(typeNumber, errorCorrectionLevel) {
    this.typeNumber = typeNumber;
    this.errorCorrectionLevel = errorCorrectionLevel;
    this.modules = null;
    this.moduleCount = 0;
    this.dataCache = null;
    this.dataList = [];
  }

  QRCodeModel.prototype = {
    addData: function(data) {
      this.dataList.push(new QR8BitByte(data));
      this.dataCache = null;
    },
    isDark: function(row, col) {
      if (row < 0 || this.moduleCount <= row || col < 0 || this.moduleCount <= col) {
        throw new Error(row + "," + col);
      }
      return this.modules[row][col];
    },
    getModuleCount: function() { return this.moduleCount; },
    make: function() {
      this.makeImpl(false, this.getBestMaskPattern());
    },
    makeImpl: function(test, maskPattern) {
      this.moduleCount = this.typeNumber * 4 + 17;
      this.modules = new Array(this.moduleCount);
      for (var row = 0; row < this.moduleCount; row++) {
        this.modules[row] = new Array(this.moduleCount);
        for (var col = 0; col < this.moduleCount; col++) {
          this.modules[row][col] = null;
        }
      }
      this.setupPositionProbePattern(0, 0);
      this.setupPositionProbePattern(this.moduleCount - 7, 0);
      this.setupPositionProbePattern(0, this.moduleCount - 7);
      this.setupTimingPattern();
      this.setupTypeInfo(test, maskPattern);
      if (this.typeNumber >= 7) { this.setupTypeNumber(test); }
      if (this.dataCache == null) {
        this.dataCache = QRCodeModel.createData(this.typeNumber, this.errorCorrectionLevel, this.dataList);
      }
      this.mapData(this.dataCache, maskPattern);
    },
    setupPositionProbePattern: function(r, c) {
      for (var row = -1; row <= 7; row++) {
        if (r + row <= -1 || this.moduleCount <= r + row) continue;
        for (var col = -1; col <= 7; col++) {
          if (c + col <= -1 || this.moduleCount <= c + col) continue;
          if ((0 <= row && row <= 6 && (col == 0 || col == 6)) ||
              (0 <= col && col <= 6 && (row == 0 || row == 6)) ||
              (2 <= row && row <= 4 && 2 <= col && col <= 4)) {
            this.modules[r + row][c + col] = true;
          } else {
            this.modules[r + row][c + col] = false;
          }
        }
      }
    },
    getBestMaskPattern: function() {
      var minLostPoint = 0;
      var pattern = 0;
      for (var i = 0; i < 8; i++) {
        this.makeImpl(true, i);
        var lostPoint = QRUtil.getLostPoint(this);
        if (i == 0 || minLostPoint > lostPoint) {
          minLostPoint = lostPoint;
          pattern = i;
        }
      }
      return pattern;
    },
    setupTimingPattern: function() {
      for (var r = 8; r < this.moduleCount - 8; r++) {
        if (this.modules[r][6] != null) continue;
        this.modules[r][6] = (r % 2 == 0);
      }
      for (var c = 8; c < this.moduleCount - 8; c++) {
        if (this.modules[6][c] != null) continue;
        this.modules[6][c] = (c % 2 == 0);
      }
    },
    setupTypeInfo: function(test, maskPattern) {
      var data = (this.errorCorrectionLevel << 3) | maskPattern;
      var bits = QRUtil.getBCHTypeInfo(data);
      for (var i = 0; i < 15; i++) {
        var mod = (!test && ((bits >> i) & 1) == 1);
        if (i < 6) { this.modules[i][8] = mod; }
        else if (i < 8) { this.modules[i + 1][8] = mod; }
        else { this.modules[this.moduleCount - 15 + i][8] = mod; }
      }
      for (var i = 0; i < 15; i++) {
        var mod = (!test && ((bits >> i) & 1) == 1);
        if (i < 8) { this.modules[8][this.moduleCount - i - 1] = mod; }
        else if (i < 9) { this.modules[8][15 - i - 1 + 1] = mod; }
        else { this.modules[8][15 - i - 1] = mod; }
      }
      this.modules[this.moduleCount - 8][8] = (!test);
    },
    mapData: function(data, maskPattern) {
      var inc = -1;
      var row = this.moduleCount - 1;
      var bitIndex = 7;
      var byteIndex = 0;
      for (var col = this.moduleCount - 1; col > 0; col -= 2) {
        if (col == 6) col--;
        while (true) {
          for (var c = 0; c < 2; c++) {
            if (this.modules[row][col - c] == null) {
              var dark = false;
              if (byteIndex < data.length) {
                dark = (((data[byteIndex] >>> bitIndex) & 1) == 1);
              }
              var mask = QRUtil.getMask(maskPattern, row, col - c);
              if (mask) dark = !dark;
              this.modules[row][col - c] = dark;
              bitIndex--;
              if (bitIndex == -1) {
                byteIndex++;
                bitIndex = 7;
              }
            }
          }
          row += inc;
          if (row < 0 || this.moduleCount <= row) {
            row -= inc;
            inc = -inc;
            break;
          }
        }
      }
    }
  };

  QRCodeModel.createData = function(typeNumber, errorCorrectionLevel, dataList) {
    var buffer = new QRBitBuffer();
    for (var i = 0; i < dataList.length; i++) {
      var data = dataList[i];
      buffer.put(data.mode, 4);
      buffer.put(data.getLength(), 8);
      data.write(buffer);
    }
    var totalDataCount = 16;
    while (buffer.length + 4 <= totalDataCount * 8) {
      buffer.put(0, 4);
    }
    while (buffer.length % 8 != 0) {
      buffer.putBit(false);
    }
    while (true) {
      if (buffer.length >= totalDataCount * 8) break;
      buffer.put(0xEC, 8);
      if (buffer.length >= totalDataCount * 8) break;
      buffer.put(0x11, 8);
    }
    return buffer.buffer;
  };

  var QRUtil = {
    getBCHTypeInfo: function(data) {
      var d = data << 10;
      while (QRUtil.getBCHDigit(d) - QRUtil.getBCHDigit(0x537) >= 0) {
        d ^= (0x537 << (QRUtil.getBCHDigit(d) - QRUtil.getBCHDigit(0x537)));
      }
      return ((data << 10) | d) ^ 0x5412;
    },
    getBCHDigit: function(data) {
      var digit = 0;
      while (data != 0) { digit++; data >>>= 1; }
      return digit;
    },
    getMask: function(maskPattern, row, col) {
      switch (maskPattern) {
        case 0: return (row + col) % 2 == 0;
        case 1: return row % 2 == 0;
        case 2: return col % 3 == 0;
        case 3: return (row + col) % 3 == 0;
        case 4: return (Math.floor(row / 2) + Math.floor(col / 3)) % 2 == 0;
        case 5: return (row * col) % 2 + (row * col) % 3 == 0;
        case 6: return ((row * col) % 2 + (row * col) % 3) % 2 == 0;
        case 7: return ((row + col) % 2 + (row * col) % 3) % 2 == 0;
        default: return false;
      }
    },
    getLostPoint: function(qr) {
      var count = qr.getModuleCount();
      var lostPoint = 0;
      for (var r = 0; r < count; r++) {
        for (var c = 0; c < count; c++) {
          var sameCount = 0;
          var dark = qr.isDark(r, c);
          for (var r2 = -1; r2 <= 1; r2++) {
            if (r + r2 < 0 || count <= r + r2) continue;
            for (var c2 = -1; c2 <= 1; c2++) {
              if (c + c2 < 0 || count <= c + c2) continue;
              if (r2 == 0 && c2 == 0) continue;
              if (dark == qr.isDark(r + r2, c + c2)) sameCount++;
            }
          }
          if (sameCount > 5) lostPoint += (3 + sameCount - 5);
        }
      }
      return lostPoint;
    }
  };

  // Interfaz pública para HTML5 Canvas
  window.QRCode = window.QRCode || {};
  window.QRCode.toCanvas = function(canvas, text, options, cb) {
    if (typeof options === 'function') { cb = options; options = {}; }
    options = options || {};

    try {
      if (!canvas) throw new Error("Canvas element is null");
      if (!text || typeof text !== 'string') text = "EP-PREVIEW";

      var size = options.width || 240;
      var margin = options.margin !== undefined ? options.margin : 1;
      var darkColor = (options.color && options.color.dark) ? options.color.dark : '#020618';
      var lightColor = (options.color && options.color.light) ? options.color.light : '#ffffff';

      var qr = new QRCodeModel(2, 0); // Modulo tipo 2 con corrección
      qr.addData(text);
      qr.make();

      var count = qr.getModuleCount();
      var ctx = canvas.getContext('2d');
      var cellSize = Math.max(2, Math.floor((size - (margin * 2)) / count));
      var actualSize = cellSize * count + (margin * 2);

      canvas.width = actualSize;
      canvas.height = actualSize;

      // Fondo
      ctx.fillStyle = lightColor;
      ctx.fillRect(0, 0, actualSize, actualSize);

      // Módulos oscuros del QR
      ctx.fillStyle = darkColor;
      for (var r = 0; r < count; r++) {
        for (var c = 0; c < count; c++) {
          if (qr.isDark(r, c)) {
            ctx.fillRect(margin + c * cellSize, margin + r * cellSize, cellSize, cellSize);
          }
        }
      }

      if (typeof cb === 'function') cb(null);
    } catch (err) {
      console.error("[QR Local Error]", err);
      if (typeof cb === 'function') cb(err);
    }
  };
})(window);